            /** @description Verified key identifier; absent for operator/service requests and pre-A5 rows. */
            clientKeyId?: string;
            /** @description Registry name captured for this request. */
            clientKeyName?: string;
            /** Format: date-time */
            startedAt: string;
            requestedModel: string;
            /**
             * @description What actually answered. Differs from the requested id after
             *     a cascade.
             */
            servedModel?: string | null;
            attempts: number;
            tier?: number;
